#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";

const PATCH = "pfotentechnik-navigation-footer-refresh-32.2.0";
const args = new Set(process.argv.slice(2));
const skipTests = args.has("--skip-tests");
const skipBuild = args.has("--skip-build");

const decode = (value) => Buffer.from(value, "base64").toString("utf8");

const HEADER_CONTENT = decode("");
const FOOTER_CONTENT = decode("");
const TEST_CONTENT = decode("");
const HEADER_LINKS_BLOCK = decode("");
const HOME_CATEGORIES_ITEMS = decode("");
const FOOTER_BLOCK = decode("");

const findRepoRoot = (start) => {
  let current = path.resolve(start);
  while (true) {
    const app = path.join(current, "apps", "pfotentechnik");
    const core = path.join(current, "packages", "affiliate-core");
    if (fs.existsSync(app) && fs.existsSync(core)) return current;
    const parent = path.dirname(current);
    if (parent === current) break;
    current = parent;
  }
  throw new Error(`[${PATCH}] Repository-Root nicht gefunden. Im affiliate-template Root ausführen.`);
};

const root = findRepoRoot(process.cwd());
const targets = {
  config: path.join(root, "apps", "pfotentechnik", "src", "project.config.ts"),
  header: path.join(root, "packages", "affiliate-core", "src", "components", "Header.astro"),
  footer: path.join(root, "packages", "affiliate-core", "src", "components", "Footer.astro"),
  legacyTheme: path.join(root, "apps", "pfotentechnik", "src", "styles", "pfotentechnik.css"),
  densityTheme: path.join(root, "apps", "pfotentechnik", "src", "styles", "pfotentechnik-visual-density.css"),
  test: path.join(root, "apps", "pfotentechnik", "test", "navigation-footer-refresh-32.2.0.test.mjs")
};

for (const [key, file] of Object.entries(targets)) {
  if (key !== "test" && !fs.existsSync(file)) {
    throw new Error(`[${PATCH}] Erwartete Datei fehlt: ${path.relative(root, file)}`);
  }
}

const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
const backupRoot = path.join(root, ".patch-backups", `${PATCH}-${timestamp}`);
let backupCreated = false;

const ensureBackup = (file) => {
  if (!fs.existsSync(file)) return;
  const relative = path.relative(root, file);
  const destination = path.join(backupRoot, relative);
  fs.mkdirSync(path.dirname(destination), { recursive: true });
  fs.copyFileSync(file, destination);
  backupCreated = true;
};

const writeIfChanged = (file, content) => {
  const normalized = content.endsWith("\n") ? content : `${content}\n`;
  const current = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : null;
  if (current === normalized) {
    console.log(`[${PATCH}] Unverändert: ${path.relative(root, file)}`);
    return false;
  }
  ensureBackup(file);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, normalized, "utf8");
  console.log(`[${PATCH}] Geschrieben: ${path.relative(root, file)}`);
  return true;
};

const findMatching = (source, openIndex, openChar, closeChar) => {
  let depth = 0;
  let quote = null;
  let escaped = false;
  let lineComment = false;
  let blockComment = false;

  for (let index = openIndex; index < source.length; index += 1) {
    const char = source[index];
    const next = source[index + 1];

    if (lineComment) {
      if (char === "\n") lineComment = false;
      continue;
    }
    if (blockComment) {
      if (char === "*" && next === "/") {
        blockComment = false;
        index += 1;
      }
      continue;
    }
    if (quote) {
      if (escaped) {
        escaped = false;
        continue;
      }
      if (char === "\\") {
        escaped = true;
        continue;
      }
      if (char === quote) quote = null;
      continue;
    }

    if (char === "/" && next === "/") {
      lineComment = true;
      index += 1;
      continue;
    }
    if (char === "/" && next === "*") {
      blockComment = true;
      index += 1;
      continue;
    }
    if (char === "\"" || char === "'" || char === "`") {
      quote = char;
      continue;
    }
    if (char === openChar) depth += 1;
    if (char === closeChar) {
      depth -= 1;
      if (depth === 0) return index;
    }
  }
  throw new Error(`[${PATCH}] Abschlusszeichen ${closeChar} nicht gefunden.`);
};

const replaceBracketedBlock = (source, marker, openChar, closeChar, replacement, fromIndex = 0) => {
  const start = source.indexOf(marker, fromIndex);
  if (start < 0) throw new Error(`[${PATCH}] Marker nicht gefunden: ${marker}`);
  const openIndex = source.indexOf(openChar, start + marker.length - 1);
  if (openIndex < 0) throw new Error(`[${PATCH}] Öffnung ${openChar} nach Marker fehlt: ${marker}`);
  const end = findMatching(source, openIndex, openChar, closeChar);
  return source.slice(0, start) + replacement + source.slice(end + 1);
};

const patchProjectConfig = (source) => {
  let next = replaceBracketedBlock(
    source,
    "  headerLinks: [",
    "[",
    "]",
    HEADER_LINKS_BLOCK
  );

  const homeStart = next.indexOf("  home: {");
  if (homeStart < 0) throw new Error(`[${PATCH}] home-Konfiguration nicht gefunden.`);
  const categoriesStart = next.indexOf("    categories: {", homeStart);
  if (categoriesStart < 0) throw new Error(`[${PATCH}] home.categories nicht gefunden.`);
  next = replaceBracketedBlock(
    next,
    "      items: [",
    "[",
    "]",
    HOME_CATEGORIES_ITEMS,
    categoriesStart
  );

  next = replaceBracketedBlock(
    next,
    "  footer: {",
    "{",
    "}",
    FOOTER_BLOCK
  );

  return next;
};

const escapeRegex = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

const removeSimpleRule = (source, selector) => {
  const pattern = new RegExp(`${escapeRegex(selector)}\\s*\\{[^{}]*\\}\\s*`, "g");
  return source.replace(pattern, "");
};

const cleanupLegacyTheme = (source) => {
  let next = source.replace(
    /,\s*\.site-header-v2 a:focus-visible,\s*\.footer-v2 a:focus-visible/g,
    ""
  );

  for (const selector of [
    ".logo-v2::before",
    ".main-nav-v2 a:hover",
    ".main-nav-v2 a",
    ".footer-column-v2 h2",
    ".site-header-v2",
    ".header-container-v2",
    ".logo-v2",
    ".nav-toggle-button",
    ".main-nav-v2",
    ".footer-v2"
  ]) {
    next = removeSimpleRule(next, selector);
  }

  for (const forbidden of [
    ".site-header-v2",
    ".header-container-v2",
    ".main-nav-v2",
    ".nav-toggle-button",
    ".footer-v2",
    ".footer-column-v2"
  ]) {
    if (next.includes(forbidden)) {
      throw new Error(`[${PATCH}] Legacy-Styles enthalten weiterhin ${forbidden}.`);
    }
  }

  return next;
};

const cleanupDensityTheme = (source) => {
  let next = source;

  for (const selector of [
    ':where(.site-header, .header-v2, header[role="banner"]) :where( .header-inner, .header-container, .header-v2__inner )',
    ':where( .menu-toggle, .nav-toggle, .mobile-menu-toggle, [aria-controls*="nav"] )',
    ':where(.main-nav-v2) > [data-pt-purchase-advice="nav"]',
    ':where(.header-advisor-link)',
    ".site-header-v2 .nav-toggle__icon > span",
    ".site-header-v2 .header-container-v2",
    ".site-header-v2 .header-advisor-link",
    ".site-header-v2 .brand-lockup",
    ".site-header-v2 .nav-toggle-button",
    ".site-header-v2 .nav-toggle__label",
    ".site-header-v2 .nav-toggle__icon",
    ".nav-toggle__icon"
  ]) {
    next = removeSimpleRule(next, selector);
  }

  next = next.replace(/@media\s*\([^{}]+\)\s*\{\s*\}\s*/g, "");

  for (const forbidden of [
    ".site-header-v2",
    ".main-nav-v2",
    ".nav-toggle-button",
    ".header-advisor-link"
  ]) {
    if (next.includes(forbidden)) {
      throw new Error(`[${PATCH}] Density-Styles enthalten weiterhin ${forbidden}.`);
    }
  }

  return next;
};

const configSource = fs.readFileSync(targets.config, "utf8");
const legacyThemeSource = fs.readFileSync(targets.legacyTheme, "utf8");
const densityThemeSource = fs.readFileSync(targets.densityTheme, "utf8");

writeIfChanged(targets.config, patchProjectConfig(configSource));
writeIfChanged(targets.header, HEADER_CONTENT);
writeIfChanged(targets.footer, FOOTER_CONTENT);
writeIfChanged(targets.legacyTheme, cleanupLegacyTheme(legacyThemeSource));
writeIfChanged(targets.densityTheme, cleanupDensityTheme(densityThemeSource));
writeIfChanged(targets.test, TEST_CONTENT);

const run = (command, commandArgs) => {
  console.log(`[${PATCH}] ${command} ${commandArgs.join(" ")}`);
  const result = spawnSync(command, commandArgs, {
    cwd: root,
    stdio: "inherit",
    shell: process.platform === "win32"
  });
  if (result.error) throw result.error;
  if (result.status !== 0) {
    throw new Error(`[${PATCH}] Befehl fehlgeschlagen (${result.status}): ${command} ${commandArgs.join(" ")}`);
  }
};

if (!skipTests) {
  run(process.execPath, [
    "--test",
    "apps/pfotentechnik/test/navigation-footer-refresh-32.2.0.test.mjs",
    "apps/pfotentechnik/test/footer-style-ownership-cleanup-26.0.5.test.mjs"
  ]);
  run("npm", [
    "--workspace",
    "apps/pfotentechnik",
    "run",
    "design-system:components:audit"
  ]);
}

if (!skipBuild) {
  run("npm", [
    "--workspace",
    "apps/pfotentechnik",
    "run",
    "build"
  ]);
}

if (backupCreated) {
  console.log(`[${PATCH}] Backup: ${path.relative(root, backupRoot)}`);
}
console.log(`[${PATCH}] Fertig.`);
